import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"02-1 一笔交易从点击按钮到执行完成：EVM 与 Gas","description":"","frontmatter":{},"headers":[],"relativePath":"02-evm/index.md","filePath":"02-evm/index.md","lastUpdated":1791601077000}'),i={name:"02-evm/index.md"};function p(l,a,r,o,d,c){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="_02-1-一笔交易从点击按钮到执行完成-evm-与-gas" tabindex="-1">02-1 一笔交易从点击按钮到执行完成：EVM 与 Gas <a class="header-anchor" href="#_02-1-一笔交易从点击按钮到执行完成-evm-与-gas" aria-label="Permalink to &quot;02-1 一笔交易从点击按钮到执行完成：EVM 与 Gas&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：弄懂你在 Remix 点击 increment 时究竟发生了什么，为什么有的操作不收费、有的交易失败了仍消耗 Gas。</p></blockquote><h2 id="从你刚才的-remix-实验出发" tabindex="-1">从你刚才的 Remix 实验出发 <a class="header-anchor" href="#从你刚才的-remix-实验出发" aria-label="Permalink to &quot;从你刚才的 Remix 实验出发&quot;">​</a></h2><p>你在 <a href="/00-start/environment">00-2</a> 做了两件事：</p><ul><li>点击 <code>number()</code>，马上得到当前数字。</li><li>点击 <code>increment()</code>，数字改变，终端里出现交易记录。</li></ul><p>它们的区别不是“按钮颜色不同”，而是<strong>是否要求区块链改变可持久化的状态</strong>。</p><h2 id="一笔写入交易的完整故事" tabindex="-1">一笔写入交易的完整故事 <a class="header-anchor" href="#一笔写入交易的完整故事" aria-label="Permalink to &quot;一笔写入交易的完整故事&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 你在界面点击 increment()</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>2. 客户端构造交易：发起地址、合约地址、调用数据等</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>3. 账户使用私钥签名（Remix VM 可代为模拟）</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>4. 通过 RPC 把交易交给网络</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>5. 节点验证交易基本规则、执行 EVM 代码</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>6. 记录成功的状态变化和事件，形成交易回执</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>7. 交易进入区块，应用检查执行状态及确认程度</span></span></code></pre></div><p>这里的 <strong>EVM</strong> 就是执行合约字节码的虚拟机。与普通服务器不同，区块链网络需要多个参与者按照相同的规则得到一致结果，所以合约不能随意向互联网发送 HTTP 请求、读取本机随机文件或直接执行系统命令。</p><h2 id="读调用为什么看似不用-gas" tabindex="-1">读调用为什么看似不用 Gas？ <a class="header-anchor" href="#读调用为什么看似不用-gas" aria-label="Permalink to &quot;读调用为什么看似不用 Gas？&quot;">​</a></h2><p>如果你通过 <code>eth_call</code> 查询 number，节点会在给定链状态上执行一个模拟调用，并把结果返回给你，但它<strong>不作为一笔新的链上交易保存</strong>，因此通常不需要支付链上交易费。</p><p>这不表示节点零成本：节点仍做计算，有些 RPC 服务商可能收 API 使用费。</p><p>如果合约 A 在<strong>一笔真实交易中调用</strong>合约 B 的 view 函数，执行计算仍会计入那笔交易的资源开销。</p><h2 id="gas-到底怎么计算-先做一道算术题" tabindex="-1">Gas 到底怎么计算？先做一道算术题 <a class="header-anchor" href="#gas-到底怎么计算-先做一道算术题" aria-label="Permalink to &quot;Gas 到底怎么计算？先做一道算术题&quot;">​</a></h2><p>记住三个词：</p><ol><li><strong>Gas Limit</strong>：为这笔交易设定的执行资源上限。</li><li><strong>Gas Used</strong>：执行实际消耗的 Gas。</li><li><strong>Effective Gas Price</strong>：每单位 Gas 最终适用的价格。</li></ol><p>举一个<strong>纯演算示例，不代表当前网络实时价格</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gas Used = 21,000</span></span>
<span class="line"><span>Effective Gas Price = 20 gwei</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行费用 = 21,000 × 20 gwei</span></span>
<span class="line"><span>         = 420,000 gwei</span></span>
<span class="line"><span>         = 0.00042 ETH</span></span></code></pre></div><p>说明：<code>1 gwei = 10^9 wei</code>，<code>1 ETH = 10^18 wei</code>。</p><p>为什么不能直接用“Gas Limit × 最高报价”作为最终费用？因为它是资源上限和最高出价相关参数，并不表示最终一定把上限全用完；另外不同网络的费用结构也可能不同。</p><h2 id="为什么写状态常比读状态贵" tabindex="-1">为什么写状态常比读状态贵？ <a class="header-anchor" href="#为什么写状态常比读状态贵" aria-label="Permalink to &quot;为什么写状态常比读状态贵？&quot;">​</a></h2><p>Solidity 的 <code>count += 1</code> 不只是 CPU 做了一次加法，它要读取、更新持久化状态。在 EVM 中，访问和修改状态需要计量相应操作的 Gas；首次写入、覆盖旧值、不同存储访问模式可能有不同费用。</p><p>你现在不需要背 Gas opcode 表，只需要建立设计意识：<strong>不要在链上毫无必要地重复保存或遍历大量数据</strong>。</p><h2 id="失败交易发生什么" tabindex="-1">失败交易发生什么？ <a class="header-anchor" href="#失败交易发生什么" aria-label="Permalink to &quot;失败交易发生什么？&quot;">​</a></h2><p>假设非 owner 调用 reset，执行到：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> owner) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Unauthorized</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>执行会失败，当前交易内的链上状态修改回滚，相关事件也不会作为成功日志保留。但执行这些检查消耗的 Gas，通常仍会由交易支付。</p><p>需要区分两种情况：</p><ul><li><strong>发送前在本地模拟就检测到错误</strong>：可能根本没有向链广播。</li><li><strong>交易已经被网络打包，执行中 revert</strong>：可在回执中查看失败状态与 Gas Used。</li></ul><p>不要把所有 UI 报错都误认为“一定已经上链并收费”。</p><h2 id="最常见的三个误解" tabindex="-1">最常见的三个误解 <a class="header-anchor" href="#最常见的三个误解" aria-label="Permalink to &quot;最常见的三个误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>实际情况</th></tr></thead><tbody><tr><td>我拿到了交易哈希，所以业务成功</td><td>不一定，还要看回执状态和确认情况</td></tr><tr><td>view 是免费的，所以完全没有计算</td><td>链下不支付链上执行费，但节点仍在算</td></tr><tr><td>合约规定“明天退款”，明天就会自己执行</td><td>不会，届时仍需要有人发送触发交易</td></tr></tbody></table><h2 id="remix-再做一次对照实验" tabindex="-1">Remix 再做一次对照实验 <a class="header-anchor" href="#remix-再做一次对照实验" aria-label="Permalink to &quot;Remix 再做一次对照实验&quot;">​</a></h2><ol><li>在虚拟链部署 <a href="/01-solidity/">OwnedCounter</a>。</li><li>点击 <code>count()</code>，观察返回值。</li><li>点击 <code>increase(3)</code>，观察成功交易记录和 Gas Used。</li><li>切换到非 owner 地址调用 <code>reset()</code>，观察失败和错误信息。</li><li>再读取 <code>count()</code>，确认失败不会把之前的 3 清掉。</li></ol><p>写一段自己的记录：哪个步骤只读、哪个修改状态、哪个 revert、各有什么可观察证据。</p><h2 id="自测-先答再看" tabindex="-1">自测（先答再看） <a class="header-anchor" href="#自测-先答再看" aria-label="Permalink to &quot;自测（先答再看）&quot;">​</a></h2><p><strong>问：</strong> 如果我在后端拿到交易哈希，是否可以立刻把订单标记为“链上付款成功”？</p><details><summary>参考答案</summary><p>不可以。需要查询交易回执、确认执行状态，并按业务风险考虑确认深度和链重组。广播成功只是交易流程中的早期步骤。</p></details><p><strong>本课验收</strong>：能解释 EVM、eth_call、Gas Used、Gas Limit、revert、receipt 的用途；能从 Remix 找到一次成功与一次失败执行的证据。</p><p>下一课：<a href="/02-evm/abi">ABI 是什么？前端如何知道该调用哪个函数</a>。</p>`,40)])])}const m=s(i,[["render",p]]);export{g as __pageData,m as default};
